export async function streamClinicianAssistant({ prompt, provider = "antigravity" }: StreamRequest) {
  const mcpTools = await octClient.listTools(); // 42 clinical tools
  const engine = provider === "grok" ? xAiGrok : provider === "antigravity" ? googleAntigravity : openAI;
  return engine.chatStream({
    messages: [{ role: "user", content: prompt }],
    tools: mcpTools,
    onProgress: (step) => emitProgressPill(step),
  });
}
